representative_inputs.schema:
entity Role enum ["owner", "developer", "operator", "orgAdmin"];

entity Environment enum ["production", "nonProduction"];

entity User {
    roles: Set<Role>,
    orgMembership: OrgUnit,
};

entity OrgUnit in [OrgUnit];

entity CloudResource {
    owner: User,
    orgUnit: OrgUnit,
    tags: Set<String>,
    environment: Environment,
    temporaryGrant: Bool,
    promoted: Bool,
};

entity Secret;

action modifyCloudResource appliesTo {
    principal: [User],
    resource: [CloudResource],
    context: {
        sourceIp: ipaddr,
        mfaUsed: Bool,
        sessionAge: duration,
    },
};

entity Role enum ["Author", "Editor", "Viewer", "ComplianceOfficer"];

entity User {
    roles: Set<Role>,
};

entity Document {
    owner: User,
    shareList: Set<User>,
    classification: String,
    hasVersionLock: Bool,
    labels: Set<String>,
    status: String,
};

entity Workspace {
    members: Set<User>,
};

action editDocument appliesTo {
    principal: [User],
    resource: [Document],
};

entity User {
    roles: Set<String>,
    clearance: Long,
};

entity EmployeeRecord {
    employee: User,
    manager: User,
    piiLevel: Long,
    department: String,
};

entity PayrollRun;

entity LeaveRequest;

action viewEmployeeRecord appliesTo {
    principal: [User],
    resource: [EmployeeRecord],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};

action preparePayrollRun appliesTo {
    principal: [User],
    resource: [PayrollRun],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};

action approveLeaveRequest appliesTo {
    principal: [User],
    resource: [LeaveRequest],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};
